import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const packageRoot = resolve(import.meta.dirname, '..', 'packages', 'dsh-whale-companion')
const assets = resolve(packageRoot, 'assets')
const output = resolve(packageRoot, 'src', 'client', 'visual-assets.ts')

const dataUrl = (filename, mime) => `data:${mime};base64,${readFileSync(resolve(assets, filename)).toString('base64')}`

writeFileSync(output, [
  '// Generated by scripts/embed-visual-assets.mjs.',
  `export const WHALE_COLLECTIBLES_ATLAS = ${JSON.stringify(dataUrl('whale-collectibles-atlas.jpg', 'image/jpeg'))}`,
  `export const WHALE_COVE_BACKGROUND = ${JSON.stringify(dataUrl('whale-cove-background.jpg', 'image/jpeg'))}`,
  '',
].join('\n'))
